INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(41311, 'Psalms 107:33', 'Psalms', 107, 33, 'هغه سیندونه کړل بدل په دښته او چینې د اوبو په وچه ځمکه باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms107_verse_33.mp3', '', 1761754199, 1761754199),
(41312, 'Psalms 107:34', 'Psalms', 107, 34, 'هغه بدله کړله ښه حاصلخېزه ځمکه په ښوره زاره ځمکه د هغو خلکو د بدۍ په سبب چې هلته اوسي په کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms107_verse_34.mp3', '', 1761754199, 1761754199),
(41313, 'Psalms 107:35', 'Psalms', 107, 35, 'هغه بدله کړله دښته په ډنډونو باندې او کړلې یې بدلې وچې ځمکې په چینو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms107_verse_35.mp3', '', 1761754199, 1761754199),
(41314, 'Psalms 107:36', 'Psalms', 107, 36, 'هلته یې راوستل وږي خلک چې په کې واوسیږي او هغوی ښار جوړ کړ چې په کې واوسیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms107_verse_36.mp3', '', 1761754199, 1761754199),
(41315, 'Psalms 107:37', 'Psalms', 107, 37, 'هغوی کښېنول تاکونه او پټي یې وکرل او ډېر حاصل یې واخیست', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms107_verse_37.mp3', '', 1761754199, 1761754199),
(41316, 'Psalms 107:38', 'Psalms', 107, 38, 'خپل قوم ته یې ورکړ برکت او اولادونه یې زیات شول او هغه پرېنښودې چې کمې شي پادې او هم رمې د هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms107_verse_38.mp3', '', 1761754199, 1761754199),
(41317, 'Psalms 107:39', 'Psalms', 107, 39, 'کله چې وخوړله ماتې د خدای قوم او سپک شول هغوی د ظالمانو له خوا او ځورېدل هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms107_verse_39.mp3', '', 1761754199, 1761754199),
(41318, 'Psalms 107:40', 'Psalms', 107, 40, 'هغه سپک کړل ظالمان خلک او خوشې صحرا کې سرګردان کړل هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms107_verse_40.mp3', '', 1761754199, 1761754199),
(41319, 'Psalms 107:41', 'Psalms', 107, 41, 'خو محتاج خلک یې بدبختۍ نه خلاص کړل او کورنۍ یې ورته زیاتې کړلې لکه رمو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms107_verse_41.mp3', '', 1761754199, 1761754199),
(41320, 'Psalms 107:42', 'Psalms', 107, 42, 'صادقان خلک چې دا ګوري نو کوي خوشحالي خو ټول بدکاره خلک چوپ پاتې شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms107_verse_42.mp3', '', 1761754199, 1761754199),
(41321, 'Psalms 107:43', 'Psalms', 107, 43, 'څوک چې هوښیار وي نو غور دې وکړي دې خبرو باندې فکر دې وکړي د څښتن د تلپاتې مینې په باب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms107_verse_43.mp3', '', 1761754199, 1761754199),
(41322, 'Psalms 130:1', 'Psalms', 130, 1, 'د ډېرې زیاتې مایوسۍ نه کړم فریاد تاته ای څښتنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms130_verse_1.mp3', '', 1761754199, 1761754199),
(41323, 'Psalms 130:2', 'Psalms', 130, 2, 'زما زارۍ واوره ای څښتنه فریاد مې واوره د کومک په خاطر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms130_verse_2.mp3', '', 1761754199, 1761754199),
(41324, 'Psalms 130:3', 'Psalms', 130, 3, 'که مو حساب د ګناهونو وکړې ای څښتنه نو څوک ستا مخکې ودرېدلی شي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms130_verse_3.mp3', '', 1761754199, 1761754199),
(41325, 'Psalms 130:4', 'Psalms', 130, 4, 'خو ته بخښونکی یې نو باید مونږ ووېرېږو ستا څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms130_verse_4.mp3', '', 1761754199, 1761754199),
(41326, 'Psalms 130:5', 'Psalms', 130, 5, 'زه څښتن ته انتظار کومه زه په خپله انتظار کومه او په کلام یې زه باور لرمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms130_verse_5.mp3', '', 1761754199, 1761754199),
(41327, 'Psalms 130:6', 'Psalms', 130, 6, 'زه انتظار کوم څښتن دپاره د دې نه زیات انتظار چې پهره‌دار یې تر سهاره کوي د دې نه زیات انتظار چې پهره‌دار یې تر سهاره کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms130_verse_6.mp3', '', 1761754199, 1761754199),
(41328, 'Psalms 130:7', 'Psalms', 130, 7, 'ای اسراییلو، په څښتن باندې باور ولرئ ځکه چې مینه یې تلپاتې ده او هغه راضي دی همېشه چې درکړي خلاصون', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms130_verse_7.mp3', '', 1761754199, 1761754199),
(41329, 'Psalms 130:8', 'Psalms', 130, 8, 'هغه په خپله به خپل قوم اسراییل له خپلو ټولو ګناهونو خلاص کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms130_verse_8.mp3', '', 1761754199, 1761754199),
(41330, 'Numbers 36:1', 'Numbers', 36, 1, 'یوه ورځ د جلعاد د طایفې د کورنیو مشران موسی او د اسراییلو نورو مشرانو ته ورغلل. (جلعاد د ماخیر زوی، ماخیر د منسي زوی او منسي د یوسف زوی ؤ.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers36_verse_1.mp3', '', 1761754199, 1761754199),
(41331, 'Numbers 36:2', 'Numbers', 36, 2, 'هغوی وویل: «باداره، څښتن تاته حکم کړی دی چې د اسراییلو خلکو ته د پچې له مخې ځمکه ووېشې. همدارنګه هغه حکم کړی دی چې زمونږ د خپلوان صلفحاد ځمکه د هغه لورګانو ته ورکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers36_verse_2.mp3', '', 1761754199, 1761754199),
(41332, 'Numbers 36:3', 'Numbers', 36, 3, 'خو دا خبره یاد ساته، که چېرې هغوی د بلې قبیلې د سړیو سره ودونه وکړي، د هغوی جایداد به د هماغې قبیلې شي او زمونږ دپاره ټاکل شوې برخه به کمه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers36_verse_3.mp3', '', 1761754199, 1761754199),
(41333, 'Numbers 36:4', 'Numbers', 36, 4, 'د بېرته ورکولو په کال کې کله چې ټول خرڅ شوی جایداد خپل اصلي خاوند ته بېرته ورکړل شي، د صلفحاد د لورګانو ځمکه به د هغې قبیلې په تلپاتې جایداد باندې ورزیاته شي په کومې کې چې هغوی واده شوې دي او دا به زمونږ د قبیلې په تاوان تمام شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers36_verse_4.mp3', '', 1761754199, 1761754199),
(41334, 'Numbers 36:5', 'Numbers', 36, 5, 'نو موسی د څښتن له خوا د اسراییلو قوم ته دغه حکم ورکړ. هغه وویل: «د منسي قبیله چې څه وایي هغه سم دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers36_verse_5.mp3', '', 1761754199, 1761754199),
(41335, 'Numbers 36:6', 'Numbers', 36, 6, 'او څښتن وایي چې د صلفحاد لورګانې ازادې دي چې د هرچا سره چې وغواړي واده کولای شي، خو یوازې په خپله قبیله کې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers36_verse_6.mp3', '', 1761754199, 1761754199),
(41336, 'Numbers 36:7', 'Numbers', 36, 7, 'په دې ډول به د هر اسراییلي جایداد د هغه د خپلې قبیلې پورې تړلی پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers36_verse_7.mp3', '', 1761754199, 1761754199),
(41337, 'Numbers 36:8', 'Numbers', 36, 8, 'هره ښځه چې د اسراییلو په یوه قبیله کې ځمکه په میراث اخلي باید د هماغې قبیلې د سړي سره واده وکړي. په دې ډول به ټولو اسراییلیانو ته د خپلو نیکونو جایداد په میراث کې ورسیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers36_verse_8.mp3', '', 1761754199, 1761754199),
(41338, 'Numbers 36:9', 'Numbers', 36, 9, 'او د یوې قبیلې ځمکه دې بلې قبیلې ته نه ورکول کیږي. هره قبیله دې خپل ملکیت وساتي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers36_verse_9.mp3', '', 1761754199, 1761754199),
(41339, 'Numbers 36:12', 'Numbers', 36, 12, 'او د منسي په قبیلې کې پاتې شوې. نو د هغوی جایداد د هغوی د پلار په قبیله کې پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers36_verse_12.mp3', '', 1761754199, 1761754199),
(41340, 'Numbers 36:13', 'Numbers', 36, 13, 'دا هغه اصول او مقررات دي چې څښتن د موسی په وسیله د موآب په ډاګونو کې د اردن د سیند په بله غاړه اریحا ته مخامخ اسراییلیانو ته ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers36_verse_13.mp3', '', 1761754199, 1761754199),
(41341, 'Proverbs 29:1', 'Proverbs', 29, 1, 'څوک چې د ډېرې رټنې نه وروسته بیا هم سرغړونه کوي نو ناڅاپه به ټوټې ټوټې شي او د جوړېدو به نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_1.mp3', '', 1761754199, 1761754199),
(41342, 'Proverbs 29:2', 'Proverbs', 29, 2, 'کله چې نېکان ابادیږي نو ټول خلک خوشحالیږي خو کله چې بدکاران واک ته رسیږي نو خلک خفه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_2.mp3', '', 1761754199, 1761754199),
(41343, 'Proverbs 29:3', 'Proverbs', 29, 3, 'څوک چې له حکمت سره مینه لري نو خپل پلار خوشحالوي خو څوک چې د بدلمنو ښځو ملګرتیا کوي نو خپل مال او دولت بربادوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_3.mp3', '', 1761754199, 1761754199),
(41344, 'Proverbs 29:4', 'Proverbs', 29, 4, 'په عدالت کولو پاچا د خپل دولت امنیت ټینګوي خو څوک چې ډېر مالیات راټولوي وطن ورانوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_4.mp3', '', 1761754199, 1761754199),
(41345, 'Proverbs 29:5', 'Proverbs', 29, 5, 'څوک چې بل چاته غوړه‌مالي کوي نو د هغه د پښو دپاره جال غوړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_5.mp3', '', 1761754199, 1761754199),
(41346, 'Proverbs 29:6', 'Proverbs', 29, 6, 'شر اچوونکی د خپلې ګناه په دام کې نښلي خو نېک انسان د خوشحالۍ سندرې وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_6.mp3', '', 1761754199, 1761754199),
(41347, 'Proverbs 29:7', 'Proverbs', 29, 7, 'نېک انسان د مسکینانو د حق پوره پام کوي خو بدکاره انسان یې خیال نه ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_7.mp3', '', 1761754199, 1761754199),
(41348, 'Proverbs 29:8', 'Proverbs', 29, 8, 'ملنډې وهونکي د اور د لمبو په شان ښارونه راپاروي خو د حکمت خاوندان د غوسې اور سړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_8.mp3', '', 1761754199, 1761754199),
(41349, 'Proverbs 29:9', 'Proverbs', 29, 9, 'که د حکمت خاوند یو جاهل محکمې ته بوځي نو جاهل به په غوسه شي او ملنډې به وهي او روغه جوړه به نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_9.mp3', '', 1761754199, 1761754199),
(41350, 'Proverbs 29:10', 'Proverbs', 29, 10, 'د وینو تږي انسانان د پاک زړه د خاوند نه کرکه کوي او هڅه کوي چې صادقان ووژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_10.mp3', '', 1761754199, 1761754199),
(41351, 'Proverbs 29:11', 'Proverbs', 29, 11, 'کم‌عقل انسان خپله غوسه زر ښکاره کوي خو د حکمت خاوند د غوسې اور سړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_11.mp3', '', 1761754199, 1761754199),
(41352, 'Proverbs 29:12', 'Proverbs', 29, 12, 'کوم واکدار چې د دروغو خبرو ته غوږ نیسي نو ټول خدمتګاران به یې بدکاره شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_12.mp3', '', 1761754199, 1761754199),
(41353, 'Proverbs 29:13', 'Proverbs', 29, 13, 'ظالم او مظلوم په یو صفت کې شریک دي ځکه څښتن دواړو ته د ژوند روښانه سترګې ورکړې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_13.mp3', '', 1761754199, 1761754199),
(41354, 'Proverbs 29:14', 'Proverbs', 29, 14, 'هغه پاچا چې په وفادارۍ د مسکینانو سره انصاف کوي نو د پاچاهۍ تخت به یې تل په ټینګ بنیاد ولاړ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_14.mp3', '', 1761754199, 1761754199),
(41355, 'Proverbs 29:15', 'Proverbs', 29, 15, 'د ادب لښته او سخته لارښوونه حکمت پیدا کوي خو کوم اولاد چې ازاد ګرځي نو خپلې مور ته شرم راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_15.mp3', '', 1761754199, 1761754199),
(41356, 'Proverbs 29:16', 'Proverbs', 29, 16, 'کله چې بدکاران واک ته رسیږي نو ګناهونه زیاتیږي خو نېکان به یې وګوري چې هغوی بربادیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_16.mp3', '', 1761754199, 1761754199),
(41357, 'Proverbs 29:17', 'Proverbs', 29, 17, 'خپل زوی اصلاح کړه نو تاته به سکون درکړي او د زړه ارمانونه به دې په خوشحالۍ پوره کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_17.mp3', '', 1761754199, 1761754199),
(41358, 'Proverbs 29:18', 'Proverbs', 29, 18, 'کله چې الهام نه وي نو ولس سرکښي کوي خو بختور دی هغه څوک چې په قانون باندې عمل کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_18.mp3', '', 1761754199, 1761754199),
(41359, 'Proverbs 29:19', 'Proverbs', 29, 19, 'نوکر یوازې په نصیحت نه اصلاح کیږي سره له دې چې هغه ستا په خبرو پوهیږي خو پام ورته نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_19.mp3', '', 1761754199, 1761754199),
(41360, 'Proverbs 29:20', 'Proverbs', 29, 20, 'څوک چې پرته له فکر کولو نه خبرې کوي نو هغه د یو کم‌عقل نه هم ډېر بد دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_20.mp3', '', 1761754199, 1761754199),
(41361, 'Proverbs 29:21', 'Proverbs', 29, 21, 'که څوک خپل نوکر د ځوانۍ نه نازولی اموخته کړي نو په اخر کې به د خپل بادار د کور او مال مالک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_21.mp3', '', 1761754199, 1761754199),
(41362, 'Proverbs 29:22', 'Proverbs', 29, 22, 'غوسه ناک انسان جنګ جګړې جوړوي او د غضب خاوند د ګناه اور ته لمن وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_22.mp3', '', 1761754199, 1761754199),
(41363, 'Proverbs 29:23', 'Proverbs', 29, 23, 'کبر او غرور انسان له پښو غورځوي خو د عاجزۍ خوی سړي ته عزت ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_23.mp3', '', 1761754199, 1761754199),
(41364, 'Proverbs 29:24', 'Proverbs', 29, 24, 'د غلو ملګری د ځان دښمن دی ځکه د قسم خوړلو نه وروسته بیا هم غلی پاتې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_24.mp3', '', 1761754199, 1761754199),
(41365, 'Proverbs 29:25', 'Proverbs', 29, 25, 'څوک چې د انسان څخه وېره کوي په دام کې به ونښلي خو څوک چې په څښتن باور کوي په امن کې به وساتل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_25.mp3', '', 1761754199, 1761754199),
(41366, 'Proverbs 29:26', 'Proverbs', 29, 26, 'ډېر خلک د واکدارانو د مهربانۍ په لټون کې دي خو انصاف د څښتن په لاس کې دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_26.mp3', '', 1761754199, 1761754199),
(41367, 'Proverbs 29:27', 'Proverbs', 29, 27, 'نېکان د منافق انسان نه کرکه کوي او بدکاران د صادق انسان نه کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs29_verse_27.mp3', '', 1761754199, 1761754199),
(41368, 'Jeremiah 48:1', 'Jeremiah', 48, 1, 'مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک د موآب په حقله فرمائى، ”په نبو ښار باندې افسوس، ځکه چې دا ښار به تباه شى. د قِريَتائم بې‌حرمتى به وشى او قبضه به کړے شى. او د مضبوطې قلعه بې‌حرمتى به وشى او ټوټه ټوټه به شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_1.mp3', '', 1761754199, 1761754199),
(41369, 'Jeremiah 48:2', 'Jeremiah', 48, 2, 'د نن نه پس به څوک هم د موآب تعريف ونۀ کړى، په حسبون کښې به خلق د هغې د راغورزولو منصوبې جوړوى، هغوئ وائى راځئ چې د موآب نوم او نشان ختم کړُو. اے د مدمين ښاريې، تۀ به هم خاموشه شې، او تاسو به په تُوره مړۀ شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_2.mp3', '', 1761754199, 1761754199),
(41370, 'Jeremiah 48:3', 'Jeremiah', 48, 3, 'د حورونايم نه د چغو آوازونو ته غوږ شئ، د لوئې تباهۍ درزار او آوازونه اورېدلے کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_3.mp3', '', 1761754199, 1761754199),
(41371, 'Jeremiah 48:4', 'Jeremiah', 48, 4, 'موآب به ټول تباه شى، د هغې واړۀ ماشومان به په تېزه چغې وهى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_4.mp3', '', 1761754199, 1761754199),
(41372, 'Jeremiah 48:5', 'Jeremiah', 48, 5, 'هغوئ لوحيت ته په بره تلو سخته ژړا کوى، او حورونايم ته په ورکوزېدو سره د تباهۍ د درزار او شور په اورېدو هغوئ په چغو چغو ژړا کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_5.mp3', '', 1761754199, 1761754199),
(41373, 'Jeremiah 48:6', 'Jeremiah', 48, 6, 'هغوئ وائى چې، منډه کړئ او ځان بچ کړئ او په صحرا کښې د ځنګلى بوټو په شان شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_6.mp3', '', 1761754199, 1761754199),
(41374, 'Jeremiah 48:7', 'Jeremiah', 48, 7, 'دا چې تا اے موآبه په خپلو اعمالو او دولت باندې باور کولو، نو تاسو به هم ګرفتار شئ، او ستا بُت کموس به هم د خپلو اِمامانو او نورو خادِمانو سره جلاوطن کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_7.mp3', '', 1761754199, 1761754199),
(41375, 'Jeremiah 48:8', 'Jeremiah', 48, 8, 'تباه کوونکے دشمن به د هر يو ښار خلاف حمله وکړى، او يو ښار به هم ترې بچ نۀ شى. هره وادى به تباه شى او هر هوار مېدان به تباه شى. ځکه چې مالِک خُدائ دا حکم کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_8.mp3', '', 1761754199, 1761754199),
(41376, 'Jeremiah 48:9', 'Jeremiah', 48, 9, 'په موآب باندې مالګه ودوړوه، ځکه چې هغه به په ښوره او صحرا بدل شى، د هغې ښارونه به وران شى، او هيڅ څوک به په کښې نۀ اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_9.mp3', '', 1761754199, 1761754199),
(41377, 'Jeremiah 48:10', 'Jeremiah', 48, 10, 'لعنت دې په هغه کسانو وى څوک چې د مالِک خُدائ په کار کښې غفلت کوى، او خپله تُوره د وينو توېدو نه بچ ساتى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_10.mp3', '', 1761754199, 1761754199),
(41378, 'Jeremiah 48:11', 'Jeremiah', 48, 11, 'موآب د ځوانۍ نه واخله تر اوسه پورې په امن او سکون سره وخت تېر کړے دے، هغه جلاوطن شوے نۀ دے. لکه څنګه چې مے په خپل لوښى کښې ځائ په ځائ پراتۀ وى، او د يو لوښى نه بل لوښى ته نۀ وى اړولے شوى. نو د هغې ذائقه هم هغه شان ده لکه څنګه چې يې د اول نه وه، او د هغې خوشبو بدله شوې نۀ ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_11.mp3', '', 1761754199, 1761754199),
(41379, 'Jeremiah 48:12', 'Jeremiah', 48, 12, 'خو هغه ورځې راروانې دى، مالِک خُدائ فرمائى چې، کله به زۀ خلق ورولېږم چې موآب د لوښى نه رابهر کړى. او هغوئ به هغه د لوښى نه لکه د ميو په شان توئ کړى او لوښى به زره زره کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_12.mp3', '', 1761754199, 1761754199),
(41380, 'Jeremiah 48:13', 'Jeremiah', 48, 13, 'نو په آخر کښې به بيا د موآب خلق د کموس بُت نه شرميږى، لکه څنګه چې بنى اِسرائيل په بيت‌ايل کښې په بُت باندې په يقين کولو شرمېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_13.mp3', '', 1761754199, 1761754199),
(41381, 'Jeremiah 48:14', 'Jeremiah', 48, 14, 'نو بيا تاسو څنګه لافې وهلې چې، مونږ په جنګ کښې ډېر تکړه او باتور فوجيان يُو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_14.mp3', '', 1761754199, 1761754199),
(41382, 'Jeremiah 48:15', 'Jeremiah', 48, 15, 'موآب به تباه شى او د هغۀ ښارونه به قبضه کړے شى. د هغۀ ښائسته زلمى به حلالېدو دپاره بوتلے شى، دا د هغه بادشاه فرمان دے چې د چا نوم مالِک خُدائ ربُ الافواج دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_15.mp3', '', 1761754199, 1761754199),
(41383, 'Jeremiah 48:16', 'Jeremiah', 48, 16, 'د موآب د ختمېدو اَنجام رانزدې شوے دے، او د هغۀ بربادى زر راتلونکى ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_16.mp3', '', 1761754199, 1761754199),
(41384, 'Jeremiah 48:17', 'Jeremiah', 48, 17, 'اے د موآب دوستانو او ګاونډيانو په دۀ باندې ماتم وکړئ، تاسو څومره چې د هغۀ د شُهرت او نوم نه واقف يئ، نو ووايئ چې، افسوس د موآب د شان او شوکت امسا ماته شوه او د هغې ټول طاقت تس نس شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_17.mp3', '', 1761754199, 1761754199),
(41385, 'Jeremiah 48:18', 'Jeremiah', 48, 18, 'اے د ديبون اوسېدونکو د خپل شاندار تخت نه راکوز شئ او په خشکه زمکه او خاورو کښېنئ، ځکه هغه چا چې موآب تباه کړو هغه به ديبون هم ټوټه ټوټه کړى. او هغه به ستاسو ټولې قلعه ګانې راوغورزوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_18.mp3', '', 1761754199, 1761754199),
(41386, 'Jeremiah 48:19', 'Jeremiah', 48, 19, 'اے د عروعير اوسېدونکو د سړک په غاړه ودرېږئ او خلقو ته وګورئ. د هغه نارينه او زناناؤ نه څوک چې تښتى تپوس وکړئ چې څۀ چل وشو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_19.mp3', '', 1761754199, 1761754199),
(41387, 'Jeremiah 48:20', 'Jeremiah', 48, 20, 'هغوئ به په جواب کښې ووائى چې، د ارنون د سيند په غاړه موآب تباه شو او په شرمونو وشرمېدو، په چغو او سورو په هغۀ ماتم او ژړا وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_20.mp3', '', 1761754199, 1761754199),
(41388, 'Jeremiah 48:21', 'Jeremiah', 48, 21, 'د مالِک خُدائ عدالت په دې غريزه مُلکونو لکه حولون، يهض، مفعت،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_21.mp3', '', 1761754199, 1761754199),
(41389, 'Jeremiah 48:22', 'Jeremiah', 48, 22, 'ديبون، نبو، بيت‌دبلاتايم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_22.mp3', '', 1761754199, 1761754199),
(41390, 'Jeremiah 48:23', 'Jeremiah', 48, 23, 'قِريَتائم، بيت‌جمول، بيت‌معون،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_23.mp3', '', 1761754199, 1761754199),
(41391, 'Jeremiah 48:24', 'Jeremiah', 48, 24, 'قريوت او بُصره او د موآب په ټولو لرې او نزدې ښارونو نازل شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_24.mp3', '', 1761754199, 1761754199),
(41392, 'Jeremiah 48:25', 'Jeremiah', 48, 25, 'مالِک خُدائ دا اعلان وکړو چې، د موآب ښکر مات شو، او د هغۀ طاقت ختم شو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_25.mp3', '', 1761754199, 1761754199),
(41393, 'Jeremiah 48:26', 'Jeremiah', 48, 26, 'مالِک خُدائ فرمائى چې، ”په موآب باندې مے وڅښئ او نشه يې کړئ، ځکه چې هغۀ خپل ځان په ما اوچت ګڼلو، پرېږده چې اوس هغه په خپلو اولټو کښې ورغړى، او پرېږده چې هغه د خلقو د خندا شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_26.mp3', '', 1761754199, 1761754199),
(41394, 'Jeremiah 48:27', 'Jeremiah', 48, 27, 'اے موآبه، آيا تا به بنى اِسرائيلو پورې خندا نۀ کوله څۀ؟ آيا ستاسو په خيال هغوئ غلۀ وُو، چې کله به تاسو د هغوئ په حقله خبرې کولې نو په مسخره آميزه توګه به مو خپل سرونه خوځول؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_27.mp3', '', 1761754199, 1761754199),
(41395, 'Jeremiah 48:28', 'Jeremiah', 48, 28, 'اے د موآب اوسېدونکو، تاسو خپل ښارونه پرېږدئ او په ګټانو کښې اوسېږئ. لکه د ګوګوشتکو په شان شئ، چې د غارونو په خولۀ کښې خپل ځان له جاله جوړوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_28.mp3', '', 1761754199, 1761754199),
(41396, 'Jeremiah 48:29', 'Jeremiah', 48, 29, 'مونږ د موآب د کبر په حقله واورېدل، ځکه چې د هغۀ بې‌حده کبر او سوچ، د هغۀ کبر او غرور او د هغۀ د زړۀ د خود غرضۍ نه خبر يُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_29.mp3', '', 1761754199, 1761754199),
(41397, 'Jeremiah 48:30', 'Jeremiah', 48, 30, 'مالِک خُدائ فرمائى چې، زۀ د هغوئ د غرور نه خبر يم خو دا بې‌مطلبه دے، او د هغوئ عملونه عبث دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_30.mp3', '', 1761754199, 1761754199),
(41398, 'Jeremiah 48:31', 'Jeremiah', 48, 31, 'نو په دې وجه زۀ په موآب ماتم کوم، زۀ د ټولو موآبيانو دپاره ژړا کوم، او زۀ د قير‌حراست د خلقو دپاره ژړا کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_31.mp3', '', 1761754199, 1761754199),
(41399, 'Jeremiah 48:32', 'Jeremiah', 48, 32, 'سبماه، زۀ به په تا وير وکړم د دې نه هم زيات چې مې په يعزير کړى وُو، سبماه ستا د انګورو څانګې تر سمندر پورې رسېدلى دى، خو تباه کوونکے ستا په مېوو او انګورو راپرېوتلے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_32.mp3', '', 1761754199, 1761754199),
(41400, 'Jeremiah 48:33', 'Jeremiah', 48, 33, 'د موآب د زرخېزه پټو او مُلک نه د خندا او خوشحالۍ آوازونه تلى دى، ما د انګورو د لنګرو نه مے جوړول بند کړى دى، هيڅ څوک هم انګور په خوشحالۍ سره نۀ نچوړوى. تر دې چې هلته شور او چغې اورېدلے شى، خو د خوشحالۍ نه بلکې د جنګ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_33.mp3', '', 1761754199, 1761754199),
(41401, 'Jeremiah 48:34', 'Jeremiah', 48, 34, 'د هغوئ د ژړا آوازونه د حسبون نه تر اِلى‌عالى او يهض پورې، او د ضُعر نه تر حورونايم پورې او عجلت‌شليشياه پورې اورېدلے شى. او تر دې چې اوس د نِمريم اوبۀ هم اوچې شوې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_34.mp3', '', 1761754199, 1761754199),
(41402, 'Jeremiah 48:35', 'Jeremiah', 48, 35, 'مالِک خُدائ فرمائى چې، زۀ به په موآب کښې هغه کسان ختم کړم څوک چې په اوچتو ځايونو کښې خپلو معبودانو ته نذرانې پېش کوى او هغوئ ته خوشبوئى سوزوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_35.mp3', '', 1761754199, 1761754199),
(41403, 'Jeremiah 48:36', 'Jeremiah', 48, 36, 'نو زما زړۀ د موآب دپاره لکه د شپيلۍ فريادونه کوى، او دا هم په قير‌حراست کښې د هغه خلقو دپاره لکه د شپيلۍ فريادونه کوى. کوم مال دولت چې هغوئ حاصل کړے وو لاړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_36.mp3', '', 1761754199, 1761754199),
(41404, 'Jeremiah 48:37', 'Jeremiah', 48, 37, 'ټولو خلقو خپل سرونه او ږيرې د غم په وجه ګنجى کړى وُو، او خپل لاسونه يې زخمى کړى وُو او د خپلو ملاګانو نه يې ټاټ تاو کړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_37.mp3', '', 1761754199, 1761754199),
(41405, 'Jeremiah 48:38', 'Jeremiah', 48, 38, 'مالِک خُدائ فرمائى چې، د موآب د هر يو کور په سر او په هره لاره او کوڅه کښې ماتم او ژړا اورېدلے کيږى. ځکه چې ما موآب لکه د هغه لوښى په شان چې څوک يې هم نۀ غواړى ټوټه ټوټه کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_38.mp3', '', 1761754199, 1761754199),
(41406, 'Jeremiah 48:39', 'Jeremiah', 48, 39, 'هاے هاے، دا څنګه ټوټه ټوټه شو. او د هغوئ چغې او سورى واورئ. د موآب شرمېدل وګورئ، دا خو ټولو خلقو او ګاونډيانو دپاره د خندا او د تباهۍ يو مثال جوړ شو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_39.mp3', '', 1761754199, 1761754199),
(41407, 'Jeremiah 48:40', 'Jeremiah', 48, 40, 'مالِک خُدائ داسې فرمائى چې، ”ګورئ، يو قوم د باز په شان خپلې وزرې خورې کړې او په موآب باندې راغوټه کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_40.mp3', '', 1761754199, 1761754199),
(41408, 'Jeremiah 48:41', 'Jeremiah', 48, 41, 'قريوت به قبضه شى او د هغۀ مضبوطې قلعه ګانې به واخستلے شى. او په هغه ورځ به د موآب د فوجيانو زړونه داسې ګبراويږى لکه چې د يوې ښځې زړۀ چې د لنګون په وخت کښې ګبراويږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_41.mp3', '', 1761754199, 1761754199),
(41409, 'Jeremiah 48:42', 'Jeremiah', 48, 42, 'موآب به نور يو قوم پاتې نۀ شى ځکه چې هغوئ خپل ځان د مالِک خُدائ نه لوئ تصور کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_42.mp3', '', 1761754199, 1761754199),
(41410, 'Jeremiah 48:43', 'Jeremiah', 48, 43, 'مالِک خُدائ فرمائى چې، دهشت، کنده او دامونه د موآب د خلقو په انتظار کښې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_43.mp3', '', 1761754199, 1761754199);